pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 depositAmount, uint256 cashOutAmount) public {
        // Restrict deposit to be above MinDeposit (1 ether) so Deposit() actually updates balances
        vm.assume(depositAmount > 1 ether);
        // Ensure cashOutAmount is not zero to avoid a trivial no-op
        vm.assume(cashOutAmount > 0);
        // Ensure cashOutAmount is <= depositAmount so the reference CashOut can succeed
        vm.assume(cashOutAmount <= depositAmount);

        // Use msg.sender as the actor
        address actor = address(this);
        vm.deal(actor, depositAmount);
        vm.startPrank(actor);

        // Deposit
        c.Deposit{value: depositAmount}();

        // Record balance before CashOut
        uint256 balanceBefore = c.balances(actor);

        // CashOut
        c.CashOut(cashOutAmount);

        vm.stopPrank();

        // After a successful CashOut, the actor's balance must have decreased
        uint256 balanceAfter = c.balances(actor);
        assertTrue(balanceAfter < balanceBefore);
    }
}

