pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 depositAmount, address actor, uint256 cashOutAmount) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        vm.assume(depositAmount >= 0.5 ether && depositAmount <= 100 ether);
        vm.assume(cashOutAmount <= 100 ether);

        // fund the actor
        vm.deal(actor, 1000 ether);

        // Make a Deposit (could be above or below MinDeposit; fuzzer decides)
        vm.prank(actor);
        try c.Deposit{value: depositAmount}() {} catch {}

        // Remember balances before a possible CashOut
        uint256 balBefore = c.balances(actor);

        // Attempt a CashOut with a fuzzed amount
        vm.prank(actor);
        bool cashoutOk = true;
        try c.CashOut(cashOutAmount) {} catch { cashoutOk = false; }

        // Read balances after attempts
        uint256 balAfter = c.balances(actor);

        if (cashoutOk) {
            // A successful CashOut must reduce the actor's balance by exactly the cashed-out amount
            assertTrue(balBefore >= cashOutAmount && balAfter == balBefore - cashOutAmount);
        }
    }
}
